    html = html.replace('  <section class="room-globe-entry"', LIVE_GLOBE_HTML + '\n<details class="live-globe-history" id="live-globe-history"><summary>History · stored activity and time sweep</summary>\n  <section class="room-globe-entry"', 1)
    return html.replace(history_html, history_html + '\n</details>', 1)
